const KEY="naxel-care-data-v1";let state=JSON.parse(localStorage.getItem(KEY)||"null")||structuredClone(seed);let route=location.hash.replace("#","")||"dashboard";const $=s=>document.querySelector(s),content=$("#content"),nav=$("#nav"),title=$("#pageTitle"),modal=$("#modalRoot");const money=v=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});const date=v=>v?new Date(v+"T12:00:00").toLocaleDateString("pt-BR"):"—";const customer=id=>state.customers.find(x=>x.id===id)||{name:"Cliente não encontrado",phone:""};const equipment=id=>state.equipment.find(x=>x.id===id)||{};const uid=p=>p+Date.now().toString().slice(-7);const save=()=>localStorage.setItem(KEY,JSON.stringify(state));const esc=s=>String(s??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
function toast(t){$("#toastRoot").insertAdjacentHTML("beforeend",`<div class="toast">${esc(t)}</div>`);setTimeout(()=>$("#toastRoot .toast")?.remove(),3200)}function renderNav(){nav.innerHTML=NAV.map(([id,l,i])=>`<button class="nav-button ${route===id?'active':''}" data-route="${id}"><span class="nav-icon">${i}</span>${l}</button>`).join("")}function intro(h,t,a=""){return `<div class="intro-row"><div><h2>${h}</h2><p>${t}</p></div>${a}</div>`}function badge(t){const c=/Vencido|Cancelado/.test(t)?"red":/Concluído|Ativa|Convertido/.test(t)?"green":"gold";return `<span class="tag ${c}">${esc(t)}</span>`}function options(items,label){return `<option value="">${label}</option>`+items.map(x=>`<option value="${x.id}">${esc(x.name||x.kind+" · "+x.brand+" "+x.model)}</option>`).join("")}
function dashboard(){const potential=state.returns.filter(x=>x.status!=="Convertido").reduce((a,b)=>a+b.value,0),priority=state.returns.filter(x=>x.status!=="Convertido").slice(0,4);content.innerHTML=`${intro("Carteira que pode voltar a gerar receita","Priorize clientes com manutenção vencida e acompanhe o valor recuperado sem procurar conversas antigas.",'<button class="secondary" data-route="returns">Ver retornos</button>')}<div class="kpis"><article class="kpi"><div class="label">Receita potencial</div><div class="value">${money(potential)}</div><div class="note">${priority.length} oportunidades abertas</div></article><article class="kpi"><div class="label">Receita recuperada</div><div class="value">${money(state.recovered)}</div><div class="note">Valor convertido em serviços</div></article><article class="kpi"><div class="label">Atendimentos</div><div class="value">${state.orders.length}</div><div class="note">${state.orders.filter(x=>x.status==="Concluído").length} concluídos</div></article><article class="kpi"><div class="label">Garantias ativas</div><div class="value">${state.warranties.filter(x=>x.status==="Ativa").length}</div><div class="note">Acompanhamento automático</div></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h3>Oportunidades prioritárias</h3><button class="link-button" data-route="returns">Abrir fila</button></div>${priority.map(r=>`<div class="opportunity"><div><strong>${esc(customer(r.customerId).name)}</strong><span>${esc(r.service)}</span>${badge(r.status)} <span>Previsto para ${date(r.due)}</span></div><div class="amount">${money(r.value)}<span>potencial</span></div></div>`).join("")||'<div class="empty-state"><strong>Fila em dia</strong><span>Nenhum retorno pendente.</span></div>'}</section><section class="panel"><div class="panel-head"><h3>Qualidade dos registros</h3></div>${[["Com equipamento",92],["Com próxima manutenção",78],["Relatórios enviados",85]].map(([l,n])=>`<div class="bar-row"><div class="bar-label"><span>${l}</span><strong>${n}%</strong></div><div class="bar"><span style="width:${n}%"></span></div></div>`).join("")}</section></div>`}
function returnsPage(){content.innerHTML=`<div class="hero-strip"><div><h2>Receita que já existe na sua carteira</h2><p>Entre em contato no momento certo e transforme manutenção esquecida em recorrência.</p></div><div class="value">${money(state.returns.filter(x=>x.status!=="Convertido").reduce((a,b)=>a+b.value,0))}</div></div><div class="toolbar"><select class="search" id="returnFilter"><option value="Todos">Todos os retornos</option><option>Vencido</option><option>Próximo</option><option>Convertido</option></select><span class="spacer"></span><button class="ghost" data-action="new-return">+ Novo retorno</button></div><div id="returnList" class="cards"></div>`;drawReturns("Todos")}
function drawReturns(f){const rows=state.returns.filter(r=>f==="Todos"||r.status===f);$("#returnList").innerHTML=rows.map(r=>{const c=customer(r.customerId),msg=encodeURIComponent(`Olá, ${c.name}! Tudo bem? Identificamos que está na hora de revisar seu equipamento. Posso reservar um horário para a ${r.service.toLowerCase()}?`);return `<article class="record-card"><div class="card-head"><div><h3>${esc(c.name)}</h3><div class="meta">${esc(r.service)}<br>Previsão: ${date(r.due)}</div></div>${badge(r.status)}</div><div class="split-line"><span class="metric-note">Potencial</span><strong>${money(r.value)}</strong></div><div class="record-actions"><a class="primary" target="_blank" rel="noopener" href="https://wa.me/55${c.phone}?text=${msg}" style="display:grid;place-items:center;text-decoration:none">WhatsApp</a><button class="ghost" data-action="convert-return" data-id="${r.id}" ${r.status==="Convertido"?"disabled":""}>Gerar atendimento</button></div></article>`}).join("")||'<div class="panel empty-state"><strong>Nada por aqui</strong><span>Altere o filtro ou adicione um retorno.</span></div>'}
function customersPage(){content.innerHTML=`${intro("Clientes e histórico em um só lugar","Consulte contatos, equipamentos instalados e atendimentos anteriores.",'<button class="secondary" data-action="new-customer">+ Novo cliente</button>')}<div class="toolbar"><input class="search" id="customerSearch" placeholder="Buscar cliente, cidade ou telefone"><span class="spacer"></span><button class="ghost" data-action="import-csv">Importar CSV</button></div><div id="customerList" class="cards"></div>`;drawCustomers("")}function drawCustomers(q){q=q.toLowerCase();$("#customerList").innerHTML=state.customers.filter(c=>[c.name,c.city,c.phone].join(" ").toLowerCase().includes(q)).map(c=>`<article class="record-card"><div class="card-head"><div><h3>${esc(c.name)}</h3><div class="meta">${esc(c.type)} · ${esc(c.city)}<br>${esc(c.phone)}${c.email?` · ${esc(c.email)}`:""}</div></div><span class="tag">${state.equipment.filter(x=>x.customerId===c.id).length} equip.</span></div><div class="record-actions"><button class="ghost" data-action="view-customer" data-id="${c.id}">Ver histórico</button><button class="primary" data-action="new-order" data-customer="${c.id}">Novo atendimento</button></div></article>`).join("")}
function equipmentPage(){content.innerHTML=`${intro("Equipamentos cadastrados","A identidade técnica de cada equipamento acompanha todo o histórico.",'<button class="secondary" data-action="new-equipment">+ Novo equipamento</button>')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Equipamento</th><th>Local</th><th>Último serviço</th><th></th></tr></thead><tbody>${state.equipment.map(e=>`<tr><td><strong>${esc(customer(e.customerId).name)}</strong></td><td>${esc(e.kind)} · ${esc(e.brand)} ${esc(e.model)}<div class="metric-note">Série ${esc(e.serial)}</div></td><td>${esc(e.location)}</td><td>${date(e.lastService)}</td><td><button data-action="view-equipment" data-id="${e.id}">Abrir →</button></td></tr>`).join("")}</tbody></table></div>`}
function ordersPage(){content.innerHTML=`${intro("Atendimentos e ordens de serviço","Da agenda à assinatura do cliente, com registro técnico completo.",'<button class="secondary" data-action="new-order">+ Novo atendimento</button>')}<div class="toolbar"><select class="search" id="orderFilter"><option>Todos</option><option>Agendado</option><option>Em campo</option><option>Concluído</option></select></div><div id="orderList" class="cards"></div>`;drawOrders("Todos")}function drawOrders(f){$("#orderList").innerHTML=state.orders.filter(o=>f==="Todos"||o.status===f).map(o=>`<article class="record-card"><div class="card-head"><div><span class="metric-note">${esc(o.id.toUpperCase())}</span><h3>${esc(customer(o.customerId).name)}</h3><div class="meta">${esc(o.service)}<br>${date(o.date)} · Técnico ${esc(o.technician||"A definir")}</div></div>${badge(o.status)}</div><div class="split-line"><span>${esc(equipment(o.equipmentId).brand||"Sem equipamento")}</span><strong>${money(o.value)}</strong></div><div class="record-actions"><button class="primary" data-action="field-mode" data-id="${o.id}">${o.status==="Concluído"?"Ver registro":"Abrir modo técnico"}</button></div></article>`).join("")||'<div class="panel empty-state"><strong>Nenhum atendimento</strong><span>Crie uma ordem para começar.</span></div>'}
function warrantiesPage(){content.innerHTML=`${intro("Garantias sem dúvida ou retrabalho","Cada garantia fica ligada ao cliente, equipamento e atendimento que a originou.")}<section class="panel"><div class="timeline">${state.warranties.map(w=>`<div class="timeline-item"><div class="card-head"><div><h3>${esc(customer(w.customerId).name)}</h3><div class="meta">Origem: ${esc(w.orderId.toUpperCase())}<br>${date(w.start)} até ${date(w.end)}</div></div>${badge(w.status)}</div></div>`).join("")||'<div>Nenhuma garantia registrada.</div>'}</div></section>`}function reportsPage(){content.innerHTML=`${intro("Laudos e comprovantes de serviço","Entregue um documento profissional ao cliente e mantenha a evidência organizada.")}<div class="cards">${state.reports.map(r=>{const o=state.orders.find(x=>x.id===r.orderId)||{};return `<article class="record-card"><div><span class="metric-note">LAUDO ${esc(r.id.toUpperCase())}</span><h3>${esc(customer(o.customerId).name)}</h3><div class="meta">Emitido em ${date(r.created)}<br>${esc(r.summary)}</div></div><div class="record-actions"><button class="ghost" data-action="view-report" data-id="${r.id}">Visualizar</button><button class="primary" data-action="share-report" data-id="${r.id}">Enviar</button></div></article>`}).join("")||'<div class="panel empty-state"><strong>Nenhum laudo ainda</strong><span>Finalize um atendimento para gerar o primeiro.</span></div>'}</div>`}
function settingsPage(){content.innerHTML=`${intro("Configurações e segurança dos dados","Os dados deste protótipo ficam neste dispositivo e podem ser exportados a qualquer momento.")}<div class="cards"><article class="record-card"><h3>Backup dos dados</h3><div class="meta">Baixe clientes, equipamentos, retornos e atendimentos em JSON.</div><button class="primary" data-action="export-data">Exportar backup</button></article><article class="record-card"><h3>Aplicativo e modo offline</h3><div class="meta">Instale o Naxel Care na tela inicial e continue consultando a operação mesmo sem conexão.</div><div class="record-actions"><button class="primary" data-action="install-app">Instalar aplicativo</button><button class="ghost" data-action="offline-demo">Testar offline</button></div></article><article class="record-card"><h3>Base de demonstração</h3><div class="meta">Volte aos registros originais usados nesta apresentação.</div><button class="ghost" data-action="reset-demo">Restaurar demonstração</button></article></div>`}
function render(){renderNav();title.textContent=NAV.find(x=>x[0]===route)?.[1]||"Naxel Care";({dashboard,returns:returnsPage,customers:customersPage,equipment:equipmentPage,orders:ordersPage,warranties:warrantiesPage,reports:reportsPage,settings:settingsPage}[route]||dashboard)()}function openModal(h,b,w=false){modal.innerHTML=`<div class="modal-backdrop"><section class="modal ${w?'wide':''}"><header class="modal-head"><h2>${h}</h2><button data-action="close-modal" aria-label="Fechar">×</button></header><div class="modal-body">${b}</div></section></div>`}function closeModal(){modal.innerHTML=""}
function newCustomer(){openModal("Novo cliente",`<form id="customerForm" class="form-grid"><div class="field full"><label>Nome ou razão social</label><input name="name" required></div><div class="field"><label>WhatsApp</label><input name="phone" required></div><div class="field"><label>E-mail</label><input name="email" type="email"></div><div class="field"><label>Cidade</label><input name="city" value="Salvador"></div><div class="field"><label>Perfil</label><select name="type"><option>Comercial</option><option>Residencial</option></select></div><div class="form-actions full"><button type="button" class="ghost" data-action="close-modal">Cancelar</button><button class="primary">Salvar cliente</button></div></form>`)}function newEquipment(){openModal("Novo equipamento",`<form id="equipmentForm" class="form-grid"><div class="field full"><label>Cliente</label><select name="customerId" required>${options(state.customers,"Selecione o cliente")}</select></div>${[["kind","Tipo","Split"],["brand","Marca",""],["model","Modelo / capacidade",""],["serial","Número de série",""] ,["location","Local instalado",""]].map(([n,l,v])=>`<div class="field"><label>${l}</label><input name="${n}" value="${v}" required></div>`).join("")}<div class="form-actions full"><button type="button" class="ghost" data-action="close-modal">Cancelar</button><button class="primary">Salvar equipamento</button></div></form>`)}
function importCsv(){openModal("Importar clientes",`<div class="import-guide"><span class="eyebrow">IMPORTAÇÃO ASSISTIDA</span><h3>Selecione sua planilha em CSV</h3><p>Reconhecemos as colunas nome, telefone, e-mail, cidade e perfil. Contatos repetidos são ignorados.</p></div><label class="photo-zone csv-zone">Escolher arquivo CSV<input id="csvFile" type="file" accept=".csv,text/csv" hidden><small>O arquivo é processado somente neste dispositivo.</small></label><div class="form-actions"><button class="ghost" data-action="download-csv-template">Baixar modelo</button><button class="ghost" data-action="close-modal">Cancelar</button></div>`)}
function splitCsvRow(row,delimiter){const values=[];let current="",quoted=false;for(let i=0;i<row.length;i++){const ch=row[i];if(ch==='"'&&row[i+1]==='"'){current+='"';i++}else if(ch==='"'){quoted=!quoted}else if(ch===delimiter&&!quoted){values.push(current.trim());current=""}else current+=ch}values.push(current.trim());return values}
async function handleCsv(file){if(!file)return;const raw=(await file.text()).replace(/^\uFEFF/,"").trim();if(!raw){toast("O arquivo está vazio");return}const lines=raw.split(/\r?\n/).filter(Boolean),delimiter=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?";":",";const normalize=s=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();const headers=splitCsvRow(lines.shift(),delimiter).map(normalize);const find=(aliases)=>headers.findIndex(h=>aliases.includes(h));const indexes={name:find(["nome","name","cliente","razao social"]),phone:find(["telefone","phone","whatsapp","celular"]),email:find(["email","e-mail"]),city:find(["cidade","city","municipio"]),type:find(["perfil","tipo","type"])};if(indexes.name<0){toast("Não encontrei uma coluna chamada nome ou cliente");return}let added=0,skipped=0;for(const line of lines){const row=splitCsvRow(line,delimiter),name=(row[indexes.name]||"").trim(),phone=indexes.phone>=0?(row[indexes.phone]||"").replace(/\D/g,""):"";if(!name)continue;const duplicate=state.customers.some(c=>(phone&&c.phone.replace(/\D/g,"")===phone)||normalize(c.name)===normalize(name));if(duplicate){skipped++;continue}state.customers.push({id:uid("c"),name,phone,email:indexes.email>=0?(row[indexes.email]||"").trim():"",city:indexes.city>=0?(row[indexes.city]||"Salvador").trim():"Salvador",type:indexes.type>=0?(row[indexes.type]||"Comercial").trim():"Comercial"});added++}save();closeModal();route="customers";location.hash=route;render();toast(`${added} cliente${added===1?"":"s"} importado${added===1?"":"s"}${skipped?` · ${skipped} repetido${skipped===1?"":"s"} ignorado${skipped===1?"":"s"}`:""}`)}
function downloadCsvTemplate(){const csv="nome;telefone;email;cidade;perfil\nEmpresa Exemplo;71999999999;contato@empresa.com;Salvador;Comercial\n";const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));a.download="modelo-clientes-naxel-care.csv";a.click();URL.revokeObjectURL(a.href);toast("Modelo CSV baixado")}
let deferredInstall=null;window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();deferredInstall=event});async function installApp(){if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;toast("Solicitação de instalação concluída");return}toast("No menu do navegador, escolha “Adicionar à tela inicial”")}
function newOrder(cid=""){openModal("Novo atendimento",`<form id="orderForm" class="form-grid"><div class="field full"><label>Cliente</label><select name="customerId" id="orderCustomer" required>${options(state.customers,"Selecione o cliente")}</select></div><div class="field full"><label>Equipamento</label><select name="equipmentId" id="orderEquipment"><option value="">Selecione o cliente primeiro</option></select></div><div class="field full"><label>Serviço</label><input name="service" value="Manutenção preventiva" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Técnico</label><input name="technician" value="Rafael"></div><div class="field"><label>Valor previsto</label><input name="value" type="number" min="0" value="350"></div><div class="form-actions full"><button type="button" class="ghost" data-action="close-modal">Cancelar</button><button class="primary">Criar atendimento</button></div></form>`);$("#orderCustomer").value=cid;fillEquipment(cid)}function fillEquipment(cid){const el=$("#orderEquipment");if(el)el.innerHTML=options(state.equipment.filter(x=>x.customerId===cid),"Sem equipamento")}
function viewCustomer(id){const c=customer(id),eq=state.equipment.filter(e=>e.customerId===id),os=state.orders.filter(o=>o.customerId===id);openModal(c.name,`<div class="hero-strip"><div><h3>${esc(c.type)} · ${esc(c.city)}</h3><p>${esc(c.phone)}${c.email?" · "+esc(c.email):""}</p></div><button class="secondary" data-action="new-order" data-customer="${c.id}">Novo atendimento</button></div><h3 class="section-title">Equipamentos</h3>${eq.map(e=>`<div class="panel"><strong>${esc(e.kind)} · ${esc(e.brand)} ${esc(e.model)}</strong><div class="meta">${esc(e.location)} · Série ${esc(e.serial)}</div></div>`).join("")||"<p>Nenhum equipamento.</p>"}<h3 class="section-title">Histórico</h3>${os.map(o=>`<div class="split-line panel"><div><strong>${esc(o.service)}</strong><div class="meta">${date(o.date)}</div></div>${badge(o.status)}</div>`).join("")||"<p>Nenhum atendimento.</p>"}`,true)}function viewEquipment(id){const e=equipment(id),os=state.orders.filter(o=>o.equipmentId===id);openModal(`${e.kind} · ${e.brand}`,`<div class="panel"><h3>${esc(e.model)}</h3><div class="meta">Cliente: ${esc(customer(e.customerId).name)}<br>Local: ${esc(e.location)}<br>Série: ${esc(e.serial)}<br>Último serviço: ${date(e.lastService)}</div></div><h3 class="section-title">Histórico técnico</h3>${os.map(o=>`<div class="split-line panel"><div><strong>${esc(o.service)}</strong><div class="meta">${date(o.date)} · ${esc(o.technician)}</div></div>${badge(o.status)}</div>`).join("")||"<p>Nenhum atendimento registrado.</p>"}`)}
function fieldMode(id){const o=state.orders.find(x=>x.id===id);if(!o)return;const done=o.status==="Concluído";openModal(`Atendimento ${o.id.toUpperCase()}`,`<div class="steps"><i class="step on"></i><i class="step on"></i><i class="step on"></i><i class="step"></i></div><div class="hero-strip"><div><h3>${esc(customer(o.customerId).name)}</h3><p>${esc(o.service)} · ${esc(equipment(o.equipmentId).location||"Equipamento não informado")}</p></div>${badge(o.status)}</div><form id="fieldForm" data-id="${o.id}"><h3>Checklist técnico</h3><div class="check-grid">${["Equipamento ligado","Filtros verificados","Drenagem testada","Temperatura conferida","Área limpa","Cliente orientado"].map((x,i)=>`<label class="check-card"><input type="checkbox" ${done||i<3?"checked":""}> ${x}</label>`).join("")}</div><h3 class="section-title">Evidências</h3><label class="photo-zone">Adicionar fotos do antes e depois<input id="photoInput" type="file" accept="image/*" multiple hidden><div id="photoPreview" class="photo-preview"></div></label><div class="field section-title"><label>Diagnóstico e serviço realizado</label><textarea name="notes" required>${done?"Serviço executado, testes realizados e funcionamento validado com o cliente.":""}</textarea></div><div class="form-grid"><div class="field"><label>Garantia em dias</label><input name="warranty" type="number" value="90"></div><div class="field"><label>Próxima manutenção</label><input name="nextDate" type="date"></div></div><h3 class="section-title">Assinatura do cliente</h3><canvas id="signature" class="signature"></canvas><div class="form-actions"><button type="button" class="ghost" data-action="close-modal">Voltar</button><button class="primary" ${done?"disabled":""}>${done?"Atendimento concluído":"Concluir e gerar laudo"}</button></div></form>`,true);signaturePad()}function signaturePad(){const c=$("#signature");if(!c)return;const x=c.getContext("2d");let d=false;const p=e=>{const r=c.getBoundingClientRect(),q=e.touches?.[0]||e;return[q.clientX-r.left,q.clientY-r.top]};c.addEventListener("pointerdown",e=>{d=true;x.beginPath();x.moveTo(...p(e))});c.addEventListener("pointermove",e=>{if(!d)return;x.lineWidth=2;x.lineCap="round";x.strokeStyle="#071827";x.lineTo(...p(e));x.stroke()});window.addEventListener("pointerup",()=>d=false)}
function viewReport(id){const r=state.reports.find(x=>x.id===id),o=state.orders.find(x=>x.id===r.orderId),c=customer(o.customerId),e=equipment(o.equipmentId);openModal("Laudo de atendimento",`<article class="panel"><div class="card-head"><div><span class="eyebrow">NAXEL CARE · COMPROVANTE TÉCNICO</span><h2>${esc(c.name)}</h2></div><strong>${esc(o.id.toUpperCase())}</strong></div><hr><p><strong>Serviço:</strong> ${esc(o.service)}</p><p><strong>Equipamento:</strong> ${esc(e.kind||"—")} · ${esc(e.brand||"")} ${esc(e.model||"")}</p><p><strong>Data:</strong> ${date(o.date)} · <strong>Técnico:</strong> ${esc(o.technician)}</p><h3 class="section-title">Resumo técnico</h3><p>${esc(r.summary)}</p><p class="metric-note">Documento gerado pelo Naxel Care. Histórico preservado para consulta e garantia.</p></article><div class="form-actions"><button class="ghost" onclick="window.print()">Imprimir / salvar PDF</button><button class="primary" data-action="share-report" data-id="${r.id}">Enviar ao cliente</button></div>`,true)}
document.addEventListener("click",e=>{const r=e.target.closest("[data-route]");if(r){route=r.dataset.route;location.hash=route;render();$(".sidebar").classList.remove("open");return}const a=e.target.closest("[data-action]");if(!a)return;const id=a.dataset.id;({"close-modal":closeModal,"new-customer":newCustomer,"new-equipment":newEquipment,"new-order":()=>newOrder(a.dataset.customer||""),"view-customer":()=>viewCustomer(id),"view-equipment":()=>viewEquipment(id),"field-mode":()=>fieldMode(id),"view-report":()=>viewReport(id),"share-report":()=>{const rep=state.reports.find(x=>x.id===id),o=state.orders.find(x=>x.id===rep.orderId),c=customer(o.customerId);window.open(`https://wa.me/55${c.phone}?text=${encodeURIComponent("Olá, "+c.name+"! Seu relatório técnico do atendimento "+o.id.toUpperCase()+" está pronto.")}`,"_blank")},"convert-return":()=>{const ret=state.returns.find(x=>x.id===id);if(ret){newOrder(ret.customerId);setTimeout(()=>{$("#orderForm [name=service]").value=ret.service;$("#orderForm [name=value]").value=ret.value},0)}},"new-return":()=>openModal("Novo retorno",`<form id="returnForm" class="form-grid"><div class="field full"><label>Cliente</label><select name="customerId" required>${options(state.customers,"Selecione")}</select></div><div class="field full"><label>Serviço recomendado</label><input name="service" required></div><div class="field"><label>Data prevista</label><input name="due" type="date" required></div><div class="field"><label>Valor potencial</label><input name="value" type="number" value="300"></div><div class="form-actions full"><button class="primary">Salvar retorno</button></div></form>`),"export-data":exportData,"offline-demo":()=>{document.body.classList.toggle("offline");toast("Modo offline simulado. Os dados continuam disponíveis.")},"reset-demo":()=>{if(confirm("Restaurar os dados de demonstração?")){state=structuredClone(seed);save();render();toast("Demonstração restaurada")}},"import-csv":()=>toast("Modelo CSV: nome, telefone, e-mail e cidade.")}[a.dataset.action]?.());});
document.addEventListener("input",e=>{if(e.target.id==="customerSearch")drawCustomers(e.target.value)});document.addEventListener("change",e=>{if(e.target.id==="returnFilter")drawReturns(e.target.value);if(e.target.id==="orderFilter")drawOrders(e.target.value);if(e.target.id==="orderCustomer")fillEquipment(e.target.value);if(e.target.id==="photoInput")$("#photoPreview").innerHTML=[...e.target.files].map(f=>`<span class="photo-chip">${esc(f.name)}</span>`).join("")});
document.addEventListener("submit",e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==="customerForm"){state.customers.push({id:uid("c"),...d});save();closeModal();route="customers";render();toast("Cliente salvo")}if(f.id==="equipmentForm"){state.equipment.push({id:uid("e"),...d,lastService:""});save();closeModal();route="equipment";render();toast("Equipamento cadastrado")}if(f.id==="orderForm"){const o={id:uid("os"),...d,value:Number(d.value),status:"Agendado"};state.orders.unshift(o);const ret=state.returns.find(x=>x.customerId===d.customerId&&x.status!=="Convertido");if(ret){ret.status="Convertido";state.recovered+=Number(ret.value)}save();closeModal();route="orders";location.hash=route;render();toast("Atendimento criado")}if(f.id==="returnForm"){state.returns.unshift({id:uid("r"),...d,value:Number(d.value),status:new Date(d.due)<new Date()?"Vencido":"Próximo"});save();closeModal();render();toast("Retorno registrado")}if(f.id==="fieldForm"){const o=state.orders.find(x=>x.id===f.dataset.id);o.status="Concluído";const eq=equipment(o.equipmentId);if(eq.id)eq.lastService=o.date;const end=new Date(o.date+"T12:00:00");end.setDate(end.getDate()+Number(d.warranty||0));state.warranties.unshift({id:uid("g"),customerId:o.customerId,orderId:o.id,start:o.date,end:end.toISOString().slice(0,10),status:"Ativa"});state.reports.unshift({id:uid("la"),orderId:o.id,created:new Date().toISOString().slice(0,10),summary:d.notes});if(d.nextDate)state.returns.unshift({id:uid("r"),customerId:o.customerId,service:"Manutenção recomendada",due:d.nextDate,value:o.value,status:"Próximo"});save();closeModal();route="reports";location.hash=route;render();toast("Atendimento concluído e laudo gerado")}});
function exportData(){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));a.download=`naxel-care-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast("Backup exportado")}$("#mobileMenu").addEventListener("click",()=>$(".sidebar").classList.toggle("open"));window.addEventListener("hashchange",()=>{route=location.hash.replace("#","")||"dashboard";render()});$("#todayLabel").textContent=new Intl.DateTimeFormat("pt-BR",{weekday:"long",day:"2-digit",month:"long"}).format(new Date()).toUpperCase();if("serviceWorker" in navigator)navigator.serviceWorker.register("./sw.js").catch(()=>{});document.body.insertAdjacentHTML("beforeend",'<div class="offline-badge">Modo offline · dados salvos neste dispositivo</div>');
async function registerWebMCP(){if(!navigator.modelContext?.registerTool)return;navigator.modelContext.registerTool({name:"list_due_returns",description:"Lista retornos de manutenção vencidos do Naxel Care",inputSchema:{type:"object",properties:{}},execute:async()=>({content:[{type:"text",text:JSON.stringify(state.returns.filter(x=>x.status==="Vencido").map(x=>({...x,customer:customer(x.customerId).name})))}]})});navigator.modelContext.registerTool({name:"create_service_order",description:"Cria uma ordem de serviço no Naxel Care",inputSchema:{type:"object",required:["customerId","service"],properties:{customerId:{type:"string"},service:{type:"string"},value:{type:"number"}}},execute:async({customerId,service,value=0})=>{const o={id:uid("os"),customerId,equipmentId:"",service,date:new Date().toISOString().slice(0,10),status:"Agendado",technician:"A definir",value};state.orders.unshift(o);save();return{content:[{type:"text",text:`Atendimento ${o.id} criado.`}]}}})}registerWebMCP();render();
document.addEventListener("click",event=>{if(event.target.classList.contains("modal-backdrop")){event.preventDefault();event.stopImmediatePropagation();closeModal();return}const action=event.target.closest("[data-action]")?.dataset.action;if(!["import-csv","install-app","download-csv-template"].includes(action))return;event.preventDefault();event.stopImmediatePropagation();if(action==="import-csv")importCsv();if(action==="install-app")installApp();if(action==="download-csv-template")downloadCsvTemplate()},true);
document.addEventListener("change",event=>{if(event.target.id==="csvFile")handleCsv(event.target.files?.[0])},true);
